mapper.select:
SELECT count(*) FROM `book_interval_record` a LEFT JOIN `book_room` b ON a.`book_id` = b.`id` LEFT JOIN `conference` c ON c.`id` = a.`conference_id`
b.`status` <> 'CANCEL_RESERVATION' and c.id = #{conferenceId}
and a.`create_time` between to_timestamp(#{startTime},'yyyy-MM-dd hh24:mi:ss') and to_timestamp(#{endTime},'yyyy-MM-dd hh24:mi:ss')
and a.create_time between #{startTime} and #{endTime}

select bir.`time_interval` ,br.`conference_id` ,br.`subscribe_person` as user_id ,br.`id` as book_id from `book_interval_record` bir inner join `book_room` br on(bir.`book_id`=br.`id`)
br.status = 'RESERVED'
and br.`conference_id` = #{param.conferenceId}
and bir.`appointment_date` =to_timestamp(#{param.date},'yyyy-MM-dd hh24:mi:ss')
and bir.`appointment_date` = #{param.date}
ORDER BY bir.`time_interval` ASC

SELECT a.`time_interval` as `periodTime`, a.`book_status` as `bookRoomEnum`, b.`name` as `name` FROM `book_time_interval` a LEFT JOIN `conference` b ON a.`conference_id` = b.`id` where b.`name` is not null
and a.`time_interval` in
#{item}

SELECT a.`time_interval` as `periodTime`, 'RESERVED' as `bookRoomEnum`, b.`name` as `name` FROM `book_interval_record` a LEFT JOIN `conference` b ON a.`conference_id` = b.`id`
and a.`time_interval` in
#{item}
and a.`appointment_date` in
to_timestamp(#{item},'yyyy-MM-dd hh24:mi:ss')
#{item}

select a.`conference_id` `conferenceId`, a.`time_interval` `timeInterval`, b.`status` FROM `book_interval_record` a LEFT JOIN `book_room` b ON a.`book_id` = b.`id` WHERE b.`status` != 'CANCEL_RESERVATION'
and a.`appointment_date` = to_timestamp(#{date},'yyyy-MM-dd hh24:mi:ss')
and a.`appointment_date` = #{date}
and a.`conference_id` in
#{item}
